/** The static sky the curtains hang in: the same values as .sheen-sky__base in backdrop.css. */
const SKY_BASE: Record<
  Theme,
  { bg: string; glows: [number, number, number, number, string, string, number][]; veil: string }
> = {
  dark: {
    bg: "oklch(12% 0.03 282)",
    glows: [
      [0.5, 1.1, 0.9, 0.6, "oklch(24% 0.1 280 / 0.6)", "oklch(24% 0.1 280 / 0)", 0.7],
      [0.55, 0.38, 0.55, 0.45, "oklch(36% 0.18 340 / 0.35)", "oklch(36% 0.18 340 / 0)", 0.72],
      [0.22, 0, 0.6, 0.5, "oklch(40% 0.2 295 / 0.5)", "oklch(40% 0.2 295 / 0)", 0.7],
      [0.78, 0.08, 0.7, 0.55, "oklch(45% 0.14 215 / 0.35)", "oklch(45% 0.14 215 / 0)", 0.7],
    ],
    veil: "oklch(12% 0.03 282 / 0.5)",
  },
  light: {
    bg: "oklch(94% 0.034 300)",
    glows: [
      [0.5, 1.1, 0.9, 0.6, "oklch(85% 0.11 70 / 0.72)", "oklch(85% 0.11 70 / 0)", 0.7],
      [0.55, 0.38, 0.55, 0.45, "oklch(80% 0.16 350 / 0.6)", "oklch(80% 0.16 350 / 0)", 0.72],
      [0.22, 0, 0.6, 0.5, "oklch(74% 0.18 300 / 0.7)", "oklch(74% 0.18 300 / 0)", 0.7],
      [0.78, 0.08, 0.7, 0.55, "oklch(78% 0.15 210 / 0.7)", "oklch(78% 0.15 210 / 0)", 0.7],
    ],
    veil: "oklch(98.2% 0.009 300 / 0.3)",
  },
};

function paintBase(theme: Theme, W: number, H: number) {
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d");
  if (!g) return c;
  const { bg, glows } = SKY_BASE[theme];
  g.fillStyle = bg;
  g.fillRect(0, 0, W, H);
  for (const [cx, cy, rx, ry, col, clear, stop] of glows) {
    g.save();
    g.translate(cx * W, cy * H);
    g.scale(rx * W, ry * H);
    const grad = g.createRadialGradient(0, 0, 0, 0, 0, 1);
    grad.addColorStop(0, col);
    grad.addColorStop(stop, clear);
    g.fillStyle = grad;
    g.fillRect(-cx / rx - 1, -cy / ry - 1, 1 / rx + 2, 1 / ry + 2);
    g.restore();
  }
  return c;
}

function makeStrip(stops: [number, string][]) {
  const c = document.createElement("canvas");
  c.width = 1;
  c.height = 256;
  const g = c.getContext("2d");
  if (!g) return c;
  const grad = g.createLinearGradient(0, 0, 0, 256);
  for (const [o, col] of stops) grad.addColorStop(o, col);
  g.fillStyle = grad;
  g.fillRect(0, 0, 1, 256);
  return c;
}

/**
 * The calm (text-safe) version of a curtain: its white-hot seams take the colour of the nearest
 * coloured stop. Body text on the bare page between panels keeps AA over it once the alpha is
 * lowered too (see `calm` below); the vivid version is for the hero's first viewport only.
 */
function calmStops(stops: [number, string][]): [number, string][] {
  const parse = (s: string) => s.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0, 0];
  const rgba = stops.map(([, s]) => parse(s));
  const isHot = (c: number[]) => Math.min(c[0] ?? 0, c[1] ?? 0, c[2] ?? 0) >= 190;
  const coloured = rgba.map((c, i) => (isHot(c) ? -1 : i)).filter((i) => i >= 0);
  return stops.map(([o, s], i) => {
    const c = rgba[i] ?? [0, 0, 0, 1];
    if (!isHot(c) || coloured.length === 0) return [o, s];
    const near = coloured.reduce((best, j) => (Math.abs(j - i) < Math.abs(best - i) ? j : best), coloured[0] ?? i);
    const [nr = 0, ng = 0, nb = 0] = rgba[near] ?? c;
    return [o, `rgba(${nr},${ng},${nb},${c[3] ?? 1})`];
  });
}

/** How much of the vivid light is left at full calm (page mode, or the hero scrolled away). */
const CALM_LIGHT = 0.34;

export default function AuroraSky({
  theme,
  reduced,
  active,
  lite,
  mode,
}: {
  theme: Theme;
  reduced: boolean;
  active: boolean;
  lite: boolean;
  mode: "hero" | "page";
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const activeRef = useRef(active);
  const kickRef = useRef<(on: boolean) => void>(() => undefined);
  const { scrollY } = useScroll();

  useEffect(() => {
    activeRef.current = active;
    kickRef.current(active);
  }, [active]);

  // Layout effect: the first frame is painted in the same commit (no blank sky on a theme switch).
  useLayoutEffect(() => {
    const canvas = ref.current;
    // Opaque: the canvas paints its own base sky, so the compositor can cull the CSS layer under it.
    const ctx = canvas?.getContext("2d", { alpha: false });
    if (!canvas || !ctx) return;
    const { composite, curtains } = CURTAINS[theme];
    const vivid = curtains.map((r) => makeStrip(r.stops));
    const calmed = curtains.map((r) => makeStrip(calmStops(r.stops)));
    // 0 = the hero's vivid sky, 1 = the text-safe page look (page mode, or the hero scrolled away).
    let calm = mode === "page" ? 1 : 0;
    const SCALE = lite ? 4 : 3;
    let W = 0;
    let H = 0;
    let aspect = 1;
    let boost = 1;
    let step = 1;
    let base: HTMLCanvasElement | null = null;
    let veil: CanvasGradient | null = null;
    let dim = 1;
    auroraSky.dawnStart ??= performance.now();
    let dawnStart = reduced ? -Infinity : auroraSky.dawnStart;
    let dawn = reduced ? 1 : 0;
    let gx = sheenPointer.x;
    let glow = 0;

    const resize = () => {
      W = Math.max(48, Math.ceil(window.innerWidth / SCALE));
      H = Math.max(48, Math.ceil(window.innerHeight / SCALE));
      aspect = Math.min(1.6, Math.max(0.55, W / H)) / 1.6;
      boost = window.innerWidth < 640 ? 1.4 : 1;
      step = W > 300 ? 2 : 1;
      canvas.width = W;
      canvas.height = H;
      base = paintBase(theme, W, H);
      veil = ctx.createLinearGradient(0, 0, 0, H);
      veil.addColorStop(0.45, SKY_BASE[theme].veil.replace(/\/ [\d.]+\)/, "/ 0)"));
      veil.addColorStop(1, SKY_BASE[theme].veil);
    };

    // The curtains are drawn into their own transparent canvas (the floor reflects only the
    // light), then laid over the base sky in one call.
    const light = document.createElement("canvas");
    const lctx = light.getContext("2d");
    if (!lctx) return;

    const drawCurtains = (t: number) => {
      const lift = reduced ? 0 : auroraSky.lift;
      const colW = step + 0.5;
      const strips = calm > 0.5 ? calmed : vivid;
      // The phone boost (curtains read faint on a narrow canvas) belongs to the vivid hero; once calm
      // it fades to 1, so bare text over the page look keeps AA on phones as it does on desktop.
      // Light-theme curtains carry deeper colours than before (vivid hero), so the calm page keeps the same measured light.
      const calmLight = theme === "light" ? CALM_LIGHT * 0.72 : CALM_LIGHT;
      const calmBoost = (boost - (boost - 1) * calm) * (1 - (1 - calmLight) * calm);
      curtains.forEach((r, i) => {
        const strip = strips[i];
        if (!strip) return;
        const f = r.freq * (0.55 + 0.45 * aspect);
        for (let x = 0; x <= W; x += step) {
          const nx = x / W;
          if (nx < r.x0 || nx > r.x1) continue;
          const ignite = clamp01(dawn * 1.9 - nx * 0.8 - i * 0.08);
          if (ignite <= 0) continue;
          const env = Math.pow(Math.sin((Math.PI * (nx - r.x0)) / (r.x1 - r.x0)), 0.7);
          const breathe = 0.74 + 0.26 * Math.sin(nx * 3.1 + t * 0.17 + r.phase);
          const raw =
            0.5 +
            0.28 * Math.sin(nx * 47 + t * 0.45 + r.phase) +
            0.15 * Math.sin(nx * 131 - t * 0.7 + r.phase * 1.7) +
            0.07 * Math.sin(nx * 293 + t * 0.9);
          const rays = 1 - r.rays * (0.65 - 0.65 * raw);
          const d = nx - gx;
          const bump = glow * Math.exp(-(d * d) / 0.012);
          const yb =
            H *
            (r.y -
              lift * 0.1 +
              (1 - ignite) * 0.09 +
              r.slope * (nx - 0.5) +
              r.amp * Math.sin(nx * f * TAU + t * r.speed + r.phase) +
              r.amp * 0.45 * Math.sin(nx * f * 2.3 * TAU - t * r.speed * 1.6 + r.phase * 2) -
              bump * 0.03);
          const h =
            H *
            r.h *
            (0.72 + 0.28 * Math.sin(nx * 4.3 - t * 0.2 + r.phase)) *
            (0.55 + 0.45 * ignite) *
            (1 + lift * 0.15);
          lctx.globalAlpha = clamp01(
            (theme === "light" ? 1 + 0.35 * (1 - calm) : 1) *
              r.alpha *
              env *
              breathe *
              rays *
              ignite *
              calmBoost *
              (1 + lift * 0.22) *
              (1 + bump * 0.55),
          );
          lctx.drawImage(strip, 0, 0, 1, 256, x - 0.25, yb - h, colW, h * 1.04);
        }
      });
    };

    const drawSky = (t: number) => {
      if (light.width !== W || light.height !== H) {
        light.width = W;
        light.height = H;
      }
      lctx.globalCompositeOperation = "source-over";
      lctx.globalAlpha = 1;
      lctx.clearRect(0, 0, W, H);
      lctx.globalCompositeOperation = composite;
      drawCurtains(t);
      ctx.globalCompositeOperation = "source-over";
      ctx.globalAlpha = 1;
      if (base) ctx.drawImage(base, 0, 0);
      ctx.globalCompositeOperation = composite;
      ctx.drawImage(light, 0, 0);
      ctx.globalCompositeOperation = "source-over";
      if (dim < 1 && base) {
        ctx.globalAlpha = 1 - dim;
        ctx.drawImage(base, 0, 0);
        ctx.globalAlpha = 1;
      }
      if (veil) {
        ctx.fillStyle = veil;
        ctx.fillRect(0, 0, W, H);
      }
    };

    // The floor reflects the band of sky where the curtains hang: flipped, squashed, rippled in
    // bands, its fade-out baked into the pixels (no CSS mask on a layer that changes per frame).
    let fade: CanvasGradient | null = null;
    let fadeH = 0;
    let measuredAt = 0;
    const drawReflection = (t: number, now: number) => {
      const rf = auroraSky.reflection;
      const rctx = rf?.getContext("2d");
      if (!rf || !rctx) return;
      if (now - measuredAt > 500) {
        measuredAt = now;
        auroraSky.measureFloor?.();
      }
      rctx.setTransform(1, 0, 0, 1, 0, 0);
      rctx.globalCompositeOperation = "source-over";
      rctx.clearRect(0, 0, rf.width, rf.height);
      if (lite) return;
      const vh = window.innerHeight;
      const horizon = auroraSky.floorTop - window.scrollY;
      if (horizon > vh + 40 || horizon + auroraSky.floorH < 0) return;
      const sy0 = H * 0.18;
      const sy1 = H * 0.72;
      if (sy1 - sy0 < 2) return;
      const RW = rf.width;
      const RH = rf.height;
      if (RW < 2 || RH < 2) return;
      const bands = 12;
      for (let b = 0; b < bands; b++) {
        const f0 = b / bands;
        const f1 = (b + 1) / bands;
        const srcTop = sy1 - (sy1 - sy0) * f1;
        const srcBot = sy1 - (sy1 - sy0) * f0;
        const dy = RH * f0;
        const dh = RH * (f1 - f0) + 0.5;
        const wob = reduced ? 0 : Math.sin(t * 1.2 + b * 0.9) * (0.4 + b * 0.35) * (RW / 240);
        rctx.setTransform(1, 0, 0, -1, wob, dy + dh);
        rctx.drawImage(light, 0, srcTop, W, srcBot - srcTop, 0, 0, RW, dh);
      }
      rctx.setTransform(1, 0, 0, 1, 0, 0);
      if (!fade || fadeH !== RH) {
        fadeH = RH;
        fade = rctx.createLinearGradient(0, 0, 0, RH);
        fade.addColorStop(0, "rgba(0,0,0,1)");
        fade.addColorStop(0.4, "rgba(0,0,0,0.8)");
        fade.addColorStop(0.72, "rgba(0,0,0,0.35)");
        fade.addColorStop(0.96, "rgba(0,0,0,0)");
      }
      rctx.globalCompositeOperation = "destination-in";
      rctx.fillStyle = fade;
      rctx.fillRect(0, 0, RW, RH);
      rctx.globalCompositeOperation = "source-over";
    };

    const redraw = () => {
      drawSky(auroraSky.clock);
      drawReflection(auroraSky.clock, performance.now());
    };

    // One sky frame per ambient beat.
    const frame = (now: number, dt: number) => {
      auroraSky.clock += dt;
      gx += (sheenPointer.x - gx) * 0.07;
      glow += ((sheenPointer.on ? 1 : 0) - glow) * 0.04;
      const p = Math.min(1, (now - dawnStart) / DAWN_MS);
      dawn = 0.5 - 0.5 * Math.cos(Math.PI * p);
      drawSky(auroraSky.clock);
      drawReflection(auroraSky.clock, now);
      auroraSky.tick.forEach((fn) => fn(auroraSky.clock));
    };

    let stop: (() => void) | null = null;
    const kick = (on: boolean) => {
      const want = on && !reduced;
      if (want === (stop !== null)) {
        // Never moving (paused from the start, or off screen at load): the still sky must be
        // the fully risen one, not an unlit pre-dawn frame.
        if (!want && dawn < 1) {
          dawn = 1;
          dawnStart = auroraSky.dawnStart = -Infinity;
          redraw();
        }
        return;
      }
      if (want) {
        stop = addAmbient(frame);
      } else {
        stop?.();
        stop = null;
        if (dawn < 1) {
          dawn = 1;
          dawnStart = auroraSky.dawnStart = -Infinity;
          redraw();
        }
      }
    };
    kickRef.current = kick;
    auroraSky.redraw = redraw;

    resize();
    redraw();
    kick(activeRef.current);

    const onResize = () => {
      resize();
      redraw();
    };
    // The aurora rises as the first viewport scrolls away, then settles deeper down the page.
    // While the loop is paused, a dim change repaints one frame (coalesced).
    let pending = 0;
    let vh = window.innerHeight;
    const onScroll = (y: number) => {
      markScrolling();
      auroraSky.lift = clamp01(y / (vh * 1.1));
      // Hero mode: the vivid sky belongs to the first viewport; by half a viewport down it has
      // calmed to the page look (body text on the bare page keeps AA over it).
      const nextCalm = mode === "page" ? 1 : clamp01((y - vh * 0.15) / (vh * 0.55));
      const deep = clamp01((y - vh * 1.8) / vh);
      const next = 1 - deep * 0.35;
      if (Math.abs(next - dim) < 0.01 && Math.abs(nextCalm - calm) < 0.01) return;
      dim = next;
      calm = nextCalm;
      if (stop === null && !pending) {
        pending = requestAnimationFrame(() => {
          pending = 0;
          drawSky(auroraSky.clock);
        });
      }
    };
    onScroll(scrollY.get());
    const offScroll = scrollY.on("change", onScroll);
    const onResizeVh = () => {
      vh = window.innerHeight;
    };
    window.addEventListener("resize", onResize);
    window.addEventListener("resize", onResizeVh);
    return () => {
      kick(false);
      cancelAnimationFrame(pending);
      kickRef.current = () => undefined;
      if (auroraSky.redraw === redraw) auroraSky.redraw = () => undefined;
      offScroll();
      window.removeEventListener("resize", onResize);
      window.removeEventListener("resize", onResizeVh);
    };
  }, [theme, reduced, lite, mode, scrollY]);

  return (
    <>
      <canvas ref={ref} className="sheen-sky__aurora" aria-hidden />
      <i className="sheen-sky__grid" />
      <i className="sheen-sky__veil" />
      <i className="sheen-sky__vignette" />
    </>
  );
}

"use client";

import { useEffect } from "react";

type NavigatorHints = Navigator & { deviceMemory?: number; connection?: { saveData?: boolean } };

/**
 * A device that should get Lite glass straight away: little memory, few
 * cores, or the visitor asked to save data.
 */
export function isWeakDevice(): boolean {
  if (typeof navigator === "undefined") return false;
  const nav = navigator as NavigatorHints;
  return (
    (nav.deviceMemory !== undefined && nav.deviceMemory <= 4) ||
    (nav.hardwareConcurrency > 0 && nav.hardwareConcurrency <= 4) ||
    nav.connection?.saveData === true
  );
}

const SETTLE_MS = 2600;
/** One verdict needs this much measured time (a first look at load, then only while the visitor scrolls or moves the pointer). */
const WINDOW_MS = 1200;
/** Below this many frames a second, in a window, the page gets Lite glass. */
const MIN_FPS = 45;
/** After this many healthy windows the probe is done: its listeners are removed and it never runs again. */
const HEALTHY_WINDOWS = 3;
/** An interaction burst ends when no scroll / pointer event has come for this long (no frame is requested while idle). */
const IDLE_MS = 160;
/** The probe gives up (never engages, never runs) this long after mount, whatever it saw. */
const GIVE_UP_MS = 60_000;

/**
 * Lite glass, automatically, on weak devices: low memory, few cores, Save-Data, or measured
 * dropped frames (under 45 fps over a 1.2 s window, measured once at load and then only while the visitor scrolls or
 * moves the pointer, up to three healthy windows or one minute).
 * Sets html[data-glass="lite"] for this visit only; a visitor's own saved choice always wins
 * (useGlassMode saves "lite" or "full").
 *
 * Call it once near the root (SheenBackdrop already does). No arguments, returns nothing.
 *
 * Accessibility: No UI of its own. Lite glass lowers blur cost only; contrast and focus rings are unchanged.
 * Glass: Switches `html[data-glass]` to "lite" (smaller blur, no refraction) for weak devices; a saved visitor choice always wins.
 * Motion: Measures frames after the entrance settles (2.6 s), then only during scroll and pointer activity; requests no frame while the page is idle or the tab is hidden, and stops after three healthy windows or one minute.
 *
 * @example
 * ```tsx
 * import type { ReactNode } from "react";
 * import { useAutoLiteGlass } from "@sheenui/theme";
 *
 * export function Root({ children }: { children: ReactNode }) {
 *   useAutoLiteGlass();
 *   return <main>{children}</main>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useAutoLiteGlass() {
  useEffect(() => {
    const root = document.documentElement;
    try {
      if (localStorage.getItem("sheen:glass")) return;
    } catch {
      /* storage blocked: decide anyway */
    }
    if (root.getAttribute("data-glass") === "full") return;
    if (isWeakDevice()) {
      root.setAttribute("data-glass", "lite");
      return;
    }
    let raf = 0;
    let timer = 0;
    let idle = 0;
    let measuring = false;
    let windows = 0;
    let start = 0;
    let frames = 0;
    let last = 0;
    let measured = 0;

    const done = () => {
      window.clearTimeout(timer);
      window.clearTimeout(idle);
      cancelAnimationFrame(raf);
      measuring = false;
      removeEventListener("scroll", wake, true);
      removeEventListener("pointermove", wake, true);
      removeEventListener("wheel", wake, true);
      removeEventListener("touchmove", wake, true);
      document.removeEventListener("visibilitychange", onHidden);
    };
    const tick = (t: number) => {
      if (!measuring) return;
      if (document.visibilityState !== "visible") {
        // Hidden: nothing counts (a browser fires no frames here anyway); the window starts over on return.
        start = frames = measured = 0;
        raf = requestAnimationFrame(tick);
        return;
      }
      if (!start) start = last = t;
      frames++;
      measured += t - last;
      last = t;
      if (measured >= WINDOW_MS) {
        const fps = ((frames - 1) * 1000) / (t - start);
        if (fps < MIN_FPS) {
          root.setAttribute("data-glass", "lite");
          done();
          return;
        }
        if (++windows >= HEALTHY_WINDOWS) {
          done();
          return;
        }
        start = last = t;
        frames = measured = 0;
      }
      raf = requestAnimationFrame(tick);
    };
    const pause = () => {
      // The visitor stopped: no more frames are requested; the partial window is dropped, not judged.
      measuring = false;
      cancelAnimationFrame(raf);
      start = frames = measured = 0;
    };
    function wake() {
      if (document.visibilityState !== "visible") return;
      window.clearTimeout(idle);
      idle = window.setTimeout(pause, IDLE_MS);
      if (measuring) return;
      measuring = true;
      raf = requestAnimationFrame(tick);
    }
    function onHidden() {
      if (document.visibilityState !== "visible") pause();
    }
    // One look at load, once the entrance has settled (the page is moving by itself: the intro, the sky): a short window.
    timer = window.setTimeout(() => {
      if (document.visibilityState === "visible") {
        measuring = true;
        raf = requestAnimationFrame(tick);
        idle = window.setTimeout(pause, WINDOW_MS * 2);
      }
      addEventListener("scroll", wake, { capture: true, passive: true });
      addEventListener("pointermove", wake, { capture: true, passive: true });
      addEventListener("wheel", wake, { capture: true, passive: true });
      addEventListener("touchmove", wake, { capture: true, passive: true });
      document.addEventListener("visibilitychange", onHidden);
      timer = window.setTimeout(done, GIVE_UP_MS);
    }, SETTLE_MS);
    return done;
  }, []);
}

"use client";

import { Suspense, lazy, useEffect, useLayoutEffect, useRef, useState } from "react";

import { useGlassMode, useReducedTransparency, useSheenStyle, type SheenStyle } from "../hooks/use-preferences";
import { cn } from "../lib/cn";
import { setBeatRate } from "../motion/beat";
import { useLoopPlayback, useMotionGate } from "../motion/gate";
import { useSheenPointerLight } from "../motion/pointer-light";
import { useAutoLiteGlass } from "./auto-lite";
import { useOsSolidGlass } from "../hooks/use-media-query";
import { observeIntersection } from "../hooks/use-intersection";
import { useResolvedScheme } from "../hooks/use-resolved-scheme";

export { useOsSolidGlass };

/*
 * <SheenBackdrop>: the page's live wallpaper, one per style preset.
 *
 *   Liquid Glass   silk ribbons, glossy spheres and daylight caustics drifting on the beat
 *   Aurora Neon    an opaque low-res canvas aurora with a dawn sweep and a floor reflection
 *
 * Rules it keeps:
 *   - a fixed sibling BEHIND the page (z-index -1): never a wrapper of glass, so every glass
 *     surface still blurs the real backdrop
 *   - static first paint in pure CSS (.sheen-sky__base); the moving layer is code-split per style
 *   - ambient motion runs only while the first viewport is on screen and the tab is visible,
 *     on ONE ~30 Hz beat shared with the pointer light (20 Hz in Lite glass)
 *   - Lite glass automatically on weak devices (useAutoLiteGlass) or by the visitor's toggle
 *   - reduced motion: a still sky; reduced transparency / forced colours: solid (CSS)
 *   - also mounts the pointer rim light for every glass surface (useSheenPointerLight)
 */

const LiquidSky = lazy(() => import("./liquid-sky"));
const AuroraSky = lazy(() => import("./aurora-sky"));

/** Props of {@link SheenBackdrop}. */
export type SheenBackdropProps = {
  /**
   * "hero": the home page look (brightest light behind the hero composition, caustics, a calm
   * veil under the copy; it settles into the page look as the first viewport scrolls away).
   * "page": the quieter docs look.
   * @default "page"
   */
  mode?: "hero" | "page";
  /** Force a style preset ("liquid" or "aurora"); defaults to the saved one (html[data-sheen-style]). */
  style?: SheenStyle;
  /**
   * Pause the ambient motion (e.g. a Pause button).
   * @default false
   */
  paused?: boolean;
  /** Adds extra classes to the fixed backdrop element. */
  className?: string;
};

/**
 * The theme actually on screen: the saved choice, or the OS setting when it is "system". Live: it
 * updates when the person switches theme or the OS flips between light and dark.
 *
 * Accessibility: No UI of its own. Server render returns "light" for "system" until hydration.
 *
 * @example
 * ```tsx
 * import { useResolvedTheme } from "@sheenui/theme";
 *
 * export function ThemeLabel() {
 *   const theme = useResolvedTheme(); // "light" | "dark"
 *   return <span>{theme === "dark" ? "Night" : "Day"}</span>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useResolvedTheme(): "light" | "dark" {
  return useResolvedScheme();
}

/**
 * The page's live wallpaper, one per style preset: silk ribbons and spheres for Liquid Glass, a
 * canvas aurora for Aurora Neon. Mount it once near the root, as a sibling before your content
 * (never a wrapper), so every glass surface blurs the real backdrop. It also mounts the pointer
 * rim light for glass surfaces.
 *
 * Props (see {@link SheenBackdropProps}): `mode` ("hero" | "page", default "page"), `style`
 * (force "liquid" or "aurora"; default the saved style), `paused` (default false), `className`.
 *
 * Accessibility: Decorative (`aria-hidden`), not focusable, and never blocks pointer events. Contrast is designed against the static base layer, so text stays readable when motion is off.
 * Glass: A fixed layer behind the page (z-index -1) with a static CSS first paint; the moving layer is code-split per style. Under reduced transparency, more contrast or forced colors it renders solid and skips the canvas work.
 * Motion: Runs on one shared ~30 Hz beat (20 Hz in Lite glass) only while the first viewport is on screen and the tab is visible. Reduced motion shows a still sky.
 *
 * @example
 * ```tsx
 * import type { ReactNode } from "react";
 * import { SheenBackdrop } from "@sheenui/theme";
 *
 * export function App({ children }: { children: ReactNode }) {
 *   return (
 *     <>
 *       <SheenBackdrop mode="page" />
 *       <main>{children}</main>
 *     </>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function SheenBackdrop({ mode = "page", style: styleProp, paused = false, className }: SheenBackdropProps) {
  const { style: savedStyle } = useSheenStyle();
  const style = styleProp ?? savedStyle;
  const theme = useResolvedTheme();
  const { reduced, pointerFx } = useMotionGate();
  const [lite] = useGlassMode();
  const [reducedTransparency] = useReducedTransparency();
  const osSolid = useOsSolidGlass();
  const solid = reducedTransparency || osSolid;
  const skyRef = useRef<HTMLDivElement>(null);
  const sentinelRef = useRef<HTMLElement>(null);
  // Ambient light plays only while the first viewport is on screen and the tab is visible.
  const playing = useLoopPlayback(sentinelRef, { paused });
  const active = playing && !solid;

  // Hero <-> page: the Liquid sky changes mode by cross-fading, never by moving. The outgoing look stays on screen as a
  // ghost layer (the previous mode, opacity-only fade-out in backdrop.css) while the incoming one sits beneath it, so the
  // orbs never change box (the live layer is keyed by mode: new nodes, no layout shift) and there is no hard cut. Reduced motion swaps instantly, without a ghost.
  const [ghost, setGhost] = useState<"hero" | "page" | null>(null);
  const lastMode = useRef(mode);
  useLayoutEffect(() => {
    const previous = lastMode.current;
    lastMode.current = mode;
    if (previous === mode) return;
    setGhost(style === "liquid" && !reduced && !solid ? previous : null);
  }, [mode, style, reduced, solid]);
  useEffect(() => {
    if (!ghost) return;
    const timer = window.setTimeout(() => setGhost(null), 420);
    return () => window.clearTimeout(timer);
  }, [ghost]);

  useAutoLiteGlass();
  useSheenPointerLight(pointerFx && !solid);

  useEffect(() => {
    setBeatRate(lite ? 20 : 30);
  }, [lite]);

  // Hero sky below the fold: once the first viewport has mostly scrolled away (the top 40 % of it is
  // gone), a veil of the page tint calms it (backdrop.css, `[data-away]`). The vivid ribbons and orbs
  // belong to the hero; the text below it (the stat cards' links, the long copy) sits on the sky
  // between the panels and needs AA over it. The veil fades in, so it is never a jump.
  useEffect(() => {
    const el = sentinelRef.current;
    const sky = skyRef.current;
    if (!el || !sky) return;
    return observeIntersection(el, (entry) => sky.toggleAttribute("data-away", !entry.isIntersecting), {
      rootMargin: "-40% 0px 0px 0px",
    });
  }, []);

  // The body's CSS blobs (backgrounds.css) would only be painted under the live sky.
  useLayoutEffect(() => {
    const root = document.documentElement;
    root.setAttribute("data-sheen-backdrop", style);
    return () => root.removeAttribute("data-sheen-backdrop");
  }, [style]);

  return (
    <>
      <div
        ref={skyRef}
        data-slot="backdrop"
        className={cn("sheen-sky", className)}
        data-style={style}
        data-mode={mode}
        data-live={active ? "" : undefined}
        aria-hidden
      >
        <div className="sheen-sky__base" />
        {!solid && (
          <Suspense fallback={null}>
            {style === "aurora" ? (
              <AuroraSky theme={theme} reduced={reduced} active={active} lite={lite} mode={mode} />
            ) : (
              <LiquidSky key={mode} mode={mode} active={active} lite={lite} />
            )}
          </Suspense>
        )}
        <div className="sheen-sky__grain" />
      </div>
      {ghost && (
        <div
          data-slot="backdrop"
          className={cn("sheen-sky sheen-sky--ghost", className)}
          data-style="liquid"
          data-mode={ghost}
          aria-hidden
        >
          <div className="sheen-sky__base" />
          <Suspense fallback={null}>
            <LiquidSky mode={ghost} active={false} lite={lite} />
          </Suspense>
        </div>
      )}
      <i ref={sentinelRef} className="sheen-sky-sentinel" aria-hidden />
    </>
  );
}

/** The one tile built so far (shared by every caller). */
let tile: Promise<string | null> | null = null;

/**
 * A bitmap grain tile for the backdrop (never SVG feTurbulence in CSS: the browser re-rasterises
 * it per tile and per zoom). Two summed randoms give grain, not speckle. Built once per page
 * and kept (one small blob URL).
 *
 * SheenBackdrop no longer calls this: its grain is a pre-baked PNG tile in styles/backdrop.css
 * (building this one costs a ~100 ms main-thread task at mount). It stays for apps that want a
 * grain of their own tint or size; set the result as `--sheen-grain-img` (and `--sheen-grain-size`).
 *
 * Browser only: it draws on a canvas, so call it from client code after mount, never during server rendering.
 */
export function grainTile(cssSize = 200, rgb: readonly [number, number, number] = [140, 140, 153], maxAlpha = 0.11) {
  tile ??= new Promise((resolve) => {
    try {
      const n = Math.round(cssSize * Math.min(2, window.devicePixelRatio || 1));
      const c = document.createElement("canvas");
      c.width = c.height = n;
      const g = c.getContext("2d");
      if (!g) {
        resolve(null);
        return;
      }
      const img = g.createImageData(n, n);
      const d = img.data;
      for (let i = 0; i < d.length; i += 4) {
        const v = (Math.random() + Math.random()) / 2;
        d[i] = rgb[0];
        d[i + 1] = rgb[1];
        d[i + 2] = rgb[2];
        d[i + 3] = Math.round(v * maxAlpha * 255);
      }
      g.putImageData(img, 0, 0);
      c.toBlob((blob) => {
        resolve(blob ? URL.createObjectURL(blob) : null);
      }, "image/png");
    } catch {
      resolve(null);
    }
  });
  return tile;
}

"use client";

import { useEffect, useId, useRef } from "react";

import { useAmbientBeat } from "../motion/beat";

/** How often the drift and caustic transforms are written (the motion is too slow to need more). */
const SKY_WRITES_PER_SECOND = 8;

/**
 * Liquid Glass wallpaper (lazy): drifting orbs, two glossy spheres and three silk ribbons inside
 * ONE drift wrapper (a single composited layer, rasterised once), plus daylight caustics.
 * Hero mode drifts on the shared ~30 Hz beat (transform only, a few px over 34 s); page mode is
 * still. Classes and placement live in styles/backdrop.css.
 */
export default function LiquidSky({ mode, active }: { mode: "hero" | "page"; active: boolean; lite: boolean }) {
  const drift = useRef<HTMLDivElement>(null);
  const caustic = useRef<HTMLElement>(null);
  const t = useRef(0);
  const lastTick = useRef(-1);
  // Where each layer sits now ("x,y" in px), so the pose can be rewritten in the other form when the sky stops or resumes.
  const pose = useRef({ drift: "-22px,14px", caustic: "0px,0px" });

  // A 3D transform (translate3d) makes its layer a compositor layer of its own for as long as it is set, even when
  // nothing moves it. While the sky plays that is what we want (the drift is a compositor shift). Once it stops (the
  // home hero's story, a hidden tab, off-screen) the same offset is rewritten as a plain 2D translate, which lets the
  // sky's layers merge into one: the glass above then blends one layer instead of several every frame it changes.
  // The picture does not move: the offset is the same.
  useEffect(() => {
    if (lastTick.current < 0) return; // never moved: nothing to rewrite
    const form = (xy: string) => (active && mode === "hero" ? `translate3d(${xy},0)` : `translate(${xy})`);
    if (drift.current) drift.current.style.transform = form(pose.current.drift);
    if (caustic.current) caustic.current.style.transform = form(pose.current.caustic);
  }, [active, mode]);

  useAmbientBeat(
    (_now, dt) => {
      t.current += dt;
      const s = t.current;
      // Both layers move under 7 px/s, so they are written together on a coarse clock (8 Hz, under a pixel per write)
      // instead of every beat: a frame in which nothing visibly moved has no damage to redraw, and the glass above the
      // sky does not re-blur the whole viewport 30 times a second for a sub-pixel change.
      const tick = Math.floor(s * SKY_WRITES_PER_SECOND);
      if (tick === lastTick.current) return;
      lastTick.current = tick;
      const at = tick / SKY_WRITES_PER_SECOND;
      // Drift: 34 s there and back (ease in-out), like the prototype's alternate keyframes. Translation only: a layer
      // that also scales or rotates is composited per pixel, several times the cost of a plain shift (the picture's
      // fixed tilt is baked into `.sheen-sky__pose`).
      const p = 0.5 - 0.5 * Math.cos((Math.PI * at) / 34);
      if (drift.current) {
        pose.current.drift = `${(-22 + 46 * p).toFixed(2)}px,${(14 - 32 * p).toFixed(2)}px`;
        drift.current.style.transform = `translate3d(${pose.current.drift},0)`;
      }
      // Caustics: a slower net of light that slides.
      const q = 0.5 - 0.5 * Math.cos((Math.PI * at) / 26);
      if (caustic.current) {
        pose.current.caustic = `${(-120 * q).toFixed(1)}px,${(80 * q).toFixed(1)}px`;
        caustic.current.style.transform = `translate3d(${pose.current.caustic},0)`;
      }
    },
    active && mode === "hero",
  );

  return (
    <div className="sheen-sky__liquid">
      <div ref={drift} className="sheen-sky__drift">
        <div className="sheen-sky__pose">
          <i className="sheen-sky__orb" data-o="a" />
          <i className="sheen-sky__orb" data-o="b" />
          <i className="sheen-sky__orb" data-o="c" />
          <i className="sheen-sky__orb" data-o="d" />
          <i className="sheen-sky__orb" data-o="e" />
          <Ribbons />
          <i className="sheen-sky__sphere" data-sphere="magenta" />
          <i className="sheen-sky__sphere" data-sphere="blue" />
        </div>
      </div>
      <div className="sheen-sky__caustics">
        <i ref={caustic} />
      </div>
      <i className="sheen-sky__veil" />
      <i className="sheen-sky__vignette" />
    </div>
  );
}

/**
 * Silk ribbons: one static SVG (no animated children, so it rasterises once and the drift
 * wrapper moves it on the compositor). Each ribbon has a fold: a shade below, a shine above,
 * and a 1.5px lit edge (emissive at night).
 */
function Ribbons() {
  const id = useId().replace(/[^\w-]/g, "");
  const ribbon = (key: string, d: string, w: number, grad: string) => (
    <g className={`sheen-ribbon sheen-ribbon--${key}`}>
      <path d={d} stroke={`url(#${id}${grad})`} strokeWidth={w} />
      <path d={d} className="sheen-ribbon__shade" strokeWidth={w * 0.36} transform={`translate(0 ${w * 0.3})`} />
      <path d={d} stroke={`url(#${id}shine)`} strokeWidth={w * 0.22} transform={`translate(0 ${-w * 0.26})`} />
      <path d={d} className="sheen-ribbon__edge" strokeWidth={1.5} transform={`translate(0 ${-w * 0.49})`} />
    </g>
  );
  return (
    <svg
      className="sheen-sky__ribbons"
      viewBox="0 0 1600 1000"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden
      focusable="false"
    >
      <defs>
        <linearGradient id={`${id}warm`} x1="0" y1="1" x2="1" y2="0">
          <stop offset="0" className="sheen-stop--1" />
          <stop offset=".38" className="sheen-stop--2" />
          <stop offset=".7" className="sheen-stop--3" />
          <stop offset="1" className="sheen-stop--4" />
        </linearGradient>
        <linearGradient id={`${id}cool`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" className="sheen-stop--5" />
          <stop offset=".5" className="sheen-stop--6" />
          <stop offset="1" className="sheen-stop--1" />
        </linearGradient>
        <linearGradient id={`${id}shine`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" />
          <stop offset=".45" stopColor="#fff" stopOpacity=".55" />
          <stop offset=".75" stopColor="#fff" stopOpacity=".15" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
      </defs>
      {ribbon("b", "M -200 330 C 240 140, 640 560, 1020 400 S 1500 60, 1820 150", 120, "cool")}
      {ribbon("a", "M -220 900 C 260 640, 560 1010, 900 760 S 1380 250, 1820 360", 190, "warm")}
      {ribbon("c", "M 420 1120 C 700 860, 980 930, 1240 690 S 1640 540, 1840 620", 64, "cool")}
    </svg>
  );
}

"use client";

import type { CSSProperties } from "react";
import { useRef } from "react";
import { motion, useScroll, useTransform } from "motion/react";

import { cn } from "../lib/cn";
import { useMotionGate } from "../motion/gate";

/** Props of {@link SheenScene}. */
export type SheenSceneProps = {
  /** The fallback image (WebP or JPEG). Required. Decorative: it gets an empty `alt`. */
  src: string;
  /** Optional AVIF source for modern browsers; the browser falls back to `src`. */
  avifSrc?: string;
  /** `srcset` of the fallback image, e.g. `"/scenes/room-800.webp 800w, /scenes/room.webp 1600w"`. */
  srcSet?: string;
  /** Sets the `srcset` of the AVIF source, like `srcSet` for the fallback image. */
  avifSrcSet?: string;
  /**
   * Sets the `sizes` attribute that tells the browser how wide the image displays, so it picks a `srcSet` candidate.
   * @default "100vw"
   */
  sizes?: string;
  /**
   * Intrinsic width of the image in pixels. It is written on the `<img>` with `height` so the browser knows the aspect
   * ratio before the file arrives; the scene itself still fills its container.
   * @default 1600
   */
  width?: number;
  /**
   * Intrinsic height of the image in pixels, written on the `<img>` with `width` to reserve its aspect ratio.
   * @default 900
   */
  height?: number;
  /**
   * How much of the page background colour is laid over the image (0 to 1). It dims the scene in
   * dark mode and washes it in light mode, so text over glass keeps 4.5:1.
   * @default 0.5
   */
  dim?: number;
  /**
   * Drift the image slowly against the scroll (transform only). Off under reduced motion; it is
   * driven by scroll progress, so nothing runs while the scene is off screen.
   * @default false
   */
  parallax?: boolean;
  /**
   * Scene is above the fold: load it eagerly with high fetch priority. Otherwise it is lazy,
   * decoded async and low priority.
   * @default false
   */
  priority?: boolean;
  /**
   * Pin the scene behind the whole page (position fixed, z-index -1) instead of filling its
   * positioned parent.
   * @default false
   */
  fixed?: boolean;
  /** Adds extra classes to the scene element. */
  className?: string;
};

/**
 * A real picture behind your glass, so the blur has something to refract. Drop it as the first
 * child of a positioned container (or pass `fixed` to pin it behind the page); glass surfaces
 * siblings above it blur the photograph. Images are yours: pass `src` (WebP/JPEG), optionally
 * `avifSrc` and `srcSet`/`avifSrcSet` for a `<picture>` with AVIF first.
 *
 * Props (see {@link SheenSceneProps}): `src` (required), `avifSrc`, `srcSet`, `avifSrcSet`,
 * `sizes` (default "100vw"), `width` (default 1600), `height` (default 900), `dim` (0 to 1, default 0.5), `parallax` (default false), `priority`
 * (default false), `fixed` (default false), `className`.
 *
 * Keyboard: Not focusable and never takes pointer events; Tab and clicks pass through to the
 * content above it.
 * Accessibility: Decorative (`aria-hidden`, empty `alt`). The `dim` layer is the page background
 * colour mixed in by token, so contrast follows light and dark mode; verify text over your own
 * image. Reduced motion turns the parallax off; reduced transparency or forced colours show the
 * solid page background instead of the image.
 * Glass: A sibling layer behind the glass, never a wrapper of it, with no opacity or filter on any
 * ancestor of glass, so every glass surface still blurs the real image.
 * Motion: Optional parallax is a scroll-linked transform (no loop, nothing runs off screen).
 *
 * @example
 * ```tsx
 * import { SheenScene } from "@sheenui/theme";
 *
 * export function Hero() {
 *   return (
 *     <section style={{ position: "relative", minHeight: 480 }}>
 *       <SheenScene
 *         src="/scenes/room.webp"
 *         avifSrc="/scenes/room.avif"
 *         srcSet="/scenes/room-800.webp 800w, /scenes/room.webp 1600w"
 *         avifSrcSet="/scenes/room-800.avif 800w, /scenes/room.avif 1600w"
 *         dim={0.4}
 *         priority
 *       />
 *       <div className="glass-2" style={{ position: "relative", padding: 24 }}>Over the scene</div>
 *     </section>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function SheenScene({
  src,
  avifSrc,
  srcSet,
  avifSrcSet,
  sizes = "100vw",
  width = 1600,
  height = 900,
  dim = 0.5,
  parallax = false,
  priority = false,
  fixed = false,
  className,
}: SheenSceneProps) {
  const { reduced } = useMotionGate();
  const ref = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "end start"] });
  const y = useTransform(scrollYProgress, [0, 1], ["-4%", "4%"]);
  const drift = parallax && !reduced;
  const amount = Math.min(1, Math.max(0, dim));

  const picture = (
    <picture>
      {avifSrc || avifSrcSet ? <source type="image/avif" srcSet={avifSrcSet ?? avifSrc} sizes={sizes} /> : null}
      <img
        className="sheen-scene__img"
        src={src}
        srcSet={srcSet}
        sizes={srcSet ? sizes : undefined}
        alt=""
        width={width}
        height={height}
        aria-hidden="true"
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        fetchPriority={priority ? "high" : "low"}
        draggable={false}
      />
    </picture>
  );

  return (
    <div
      ref={ref}
      aria-hidden="true"
      data-slot="scene"
      data-sheen-scene=""
      data-fixed={fixed ? "" : undefined}
      data-parallax={drift ? "" : undefined}
      className={cn("sheen-scene", className)}
      style={{ "--sheen-scene-dim": amount } as CSSProperties}
    >
      {drift ? (
        <motion.div className="sheen-scene__layer" style={{ y }}>
          {picture}
        </motion.div>
      ) : (
        <div className="sheen-scene__layer">{picture}</div>
      )}
      <span className="sheen-scene__dim" />
    </div>
  );
}

"use client";

import { useEffect } from "react";

import { useLatest } from "../hooks/use-latest";

/**
 * Shared, module-level state of the Aurora sky, so a theme switch or a remount never makes the
 * light jump, and so page content can hang off the sky's clock:
 *   - `clock`      seconds on the sky's own clock (46 s is a good-looking moment of the loop: also
 *                  the reduced-motion still)
 *   - `lift`       0..1, the aurora rises and brightens as the first viewport scrolls away
 *   - `reflection` a canvas the sky paints its mirror image into (a hero's glossy floor), see
 *                  registerAuroraFloor
 *   - `tick`       ambient movers called on every sky frame (never under reduced motion)
 */
export const auroraSky = {
  clock: 46,
  dawnStart: null as number | null,
  lift: 0,
  reflection: null as HTMLCanvasElement | null,
  /** The floor's top edge in document px and its height; kept fresh by `measureFloor`. */
  floorTop: 0,
  floorH: 0,
  measureFloor: null as (() => void) | null,
  tick: new Set<(t: number) => void>(),
  /** Paint one still frame now (set by the sky; a no-op without one). */
  redraw: (): void => undefined,
};

/**
 * Give the sky a floor to reflect in. `measure` is called by the sky at most twice a second
 * while the floor is near the viewport; it should set `auroraSky.floorTop` / `floorH` (document
 * px) and size the canvas. Returns the unregister function.
 */
export function registerAuroraFloor(canvas: HTMLCanvasElement, measure: () => void) {
  auroraSky.reflection = canvas;
  auroraSky.measureFloor = measure;
  measure();
  auroraSky.redraw();
  return () => {
    if (auroraSky.reflection === canvas) {
      auroraSky.reflection = null;
      auroraSky.measureFloor = null;
    }
  };
}

/**
 * Run `cb(skyClockSeconds)` on every Aurora sky frame while mounted (pass null to stop). Use it to
 * hang page content off the sky's clock (a glow that breathes with the aurora). The latest `cb`
 * is always used, so an inline function is fine. Never called under reduced motion.
 *
 * Accessibility: No UI of its own; keep what you animate decorative.
 * Motion: Ticks only while the Aurora sky is playing (first viewport visible, tab visible, motion allowed).
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { Badge } from "@sheenui/theme";
 *
 * // Placeholder: an internal hook of the style engine, not part of the package entry.
 * declare function useSkyTick(cb: ((t: number) => void) | null): void;
 *
 * export function Glow() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   useSkyTick((t) => {
 *     if (ref.current) ref.current.style.opacity = String(0.6 + 0.4 * Math.sin(t));
 *   });
 *   return <div ref={ref} className="glow"><Badge>Aurora</Badge></div>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useSkyTick(cb: ((t: number) => void) | null) {
  const latestRef = useLatest(cb);
  const on = cb !== null;
  useEffect(() => {
    if (!on) return;
    const fn = (t: number) => latestRef.current?.(t);
    auroraSky.tick.add(fn);
    return () => {
      auroraSky.tick.delete(fn);
    };
  }, [on, latestRef]);
}

